1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.repository.OwnerRepository;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	
11	/**
12	 * When a create-owner request opts in with {@code sharesHousehold=true} and an existing owner already
13	 * occupies its household (same last name and address, per {@link Household}), gives the new owner and
14	 * every existing member one shared {@code householdId}: an id already held by a member is reused,
15	 * otherwise a stable one is derived and back-filled onto the existing members so all members agree.
16	 * Runs under the request transaction, after the owner entity is built.
17	 */
18	public class AssignHousehold {
19	
20	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
21	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
22	            return;
23	        }
24	        List<Owner> members = new ArrayList<>();
25	        for (Owner existing : ownerRepository.findByLastName(request.getLastName())) {
26	            if (Household.matches(existing, request.getLastName(), request.getAddress())) {
27	                members.add(existing);
28	            }
29	        }
30	        if (members.isEmpty()) {
31	            return;
32	        }
33	        String householdId = members.stream()
34	                .map(Owner::getHouseholdId)
35	                .filter(id -> id != null && !id.isBlank())
36	                .findFirst()
37	                .orElseGet(() -> Household.idFor(request.getLastName(), request.getAddress()));
38	        owner.setHouseholdId(householdId);
39	        for (Owner member : members) {
40	            if (!householdId.equals(member.getHouseholdId())) {
41	                member.setHouseholdId(householdId);
42	                ownerRepository.save(member);
43	            }
44	        }
45	    }
46	}
